public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Initialize the bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<V, E>();

    // Add nodes from the left-hand side of the input graph
    for (V vertex : target.getLeftVertices()) {
        bipartiteGraph.addNode(vertex);
    }

    // Add nodes from the right-hand side of the input graph
    for (V vertex : target.getRightVertices()) {
        bipartiteGraph.addNode(vertex);
    }

    // Add edges connections between the two sides of the graph
    for (E edge : target.getEdges()) {
        V leftNode = edge.getLeftVertex();
        V rightNode = edge.getRightVertex();
        bipartiteGraph.addEdge(leftNode, rightNode);
    }
}

