public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Validate inputs
    if (out == null) {
        throw new IllegalArgumentException("Output stream must not be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message must not be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema must not be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    // Serialize the message
    int size = schema.getSerializedSize(message, buffer);
    ByteArrayOutputStream byteOut = new ByteArrayOutputStream(size);
    CodedOutputStream codedOut = CodedOutputStream.newInstance(byteOut);
    schema.writeTo(codedOut, message);
    codedOut.flush();
    // Write the message size
    codedOut.writeUInt32NoTag(size);
    byteOut.writeTo(out);
    return size;
}

