public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            throw new NullPointerException("byteArrayValue");
        }
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid byteOffset (" + byteOffset + ") or byteLength (" + byteLength + "), must have 0 <= byteOffset < " + byteArrayValue.length + " and 0 < byteLength <= " + byteArrayValue.length + " + byteOffset");
        }
        if (byteLength == 0) {
            return this;
        }
        if (byteArrayValue.length + byteOffset > this.data.length) {
            this.enlarge(byteArrayValue.length + byteOffset);
        }
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
        this.length += byteLength;
        return this;
    }

