public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (decode) {
        try {
            path = URLDecoder.decode(path, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            throw new IllegalArgumentException("Failed to decode URL", e);
        }
    }
    String[] tokens = path.split("/", -1);
    for (int i = 0; i < tokens.length; i++) {
        String token = tokens[i];
        if (token.isEmpty()) {
            continue;
        }
        PathSegmentImpl segment = new PathSegmentImpl(token, i == 0 && path.startsWith("/") ? PathSegmentImpl.Type.ABSOLUTE : PathSegmentImpl.Type.SEGMENT);
        segments.add(segment);
    }
    return segments;
}

