    }
    if (off < 0 || off >= b.length) {
        throw new IndexOutOfBoundsException("The offset must be a valid index into the byte array");
    }
    if (len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("The length must be a valid number of bytes to write");
    }
    if (writePos + len >= capacity) {
