        throw new IllegalArgumentException("Target vertex not in graph: " + targetVertex);
    }
    if (!this.edges.containsKey(e)) {
        throw new IllegalArgumentException("Edge not in graph: " + e);
    }

    GraphEdge<V, E> graphEdge = this.edges.get(e);
    if (graphEdge.getSourceVertex() != sourceVertex) {
        throw new IllegalArgumentException("Edge has wrong source vertex: " + graphEdge.getSourceVertex() + " != " + sourceVertex);
    }
    if (graphEdge.getTargetVertex() != targetVertex) {
        throw new IllegalArgumentException("Edge has wrong target vertex: " + graphEdge.getTargetVertex() + " != " + targetVertex);
    }

    this.outgoingEdges.put(sourceVertex, new LinkedHashMap<>());
    this.incomingEdges.put(targetVertex, new LinkedHashMap<>());
    this.outgoingEdges.put(sourceVertex, new LinkedHashMap<>());
    this.incomingEdges.put(targetVertex, new LinkedHashMap<>());
    graphEdge.setIndex(e, this.edges.size() - 1);
    this.edges.put(e, graphEdge);
    this.sourceVertices.put(e, sourceVertex);
    this.targetVertices.put(e, targetVertex);
    this.edgeCount++;
}

