public Object convertToType(final Class<?> type,final Object value) throws Exception {
    Object result;

    if (type == null) {
        throw new Exception("target type can't be null");
    } else if (type != Character.class) {
        throw new Exception(String.format("target type %s is not supported", type.getName()));
    }

    if (value == null) {
        result = '\u0000';
    } else if (value instanceof String) {
        String string = (String) value;
        if (string.isEmpty()) {
            result = '\u0000';
        } else {
            result = string.charAt(0);
        }
    } else if (value instanceof Number) {
        Number number = (Number) value;
        result = (char) number.intValue();
    } else {
        throw new Exception(String.format("input value of type %s can't be converted to Character", value.getClass().getName()));
    }

    return result;
}

