public static int nextPrime(int desiredCapacity) {
    desiredCapacity = Math.max(1, Math.min(Integer.MAX_VALUE - 1, desiredCapacity));
    boolean isPrime = false;
    while (!isPrime) {
        if (desiredCapacity % 2 == 0 || desiredCapacity % 3 == 0 || desiredCapacity % 5 == 0 || desiredCapacity % 7 == 0) {
            desiredCapacity++;
        } else {
            boolean isComposite = false;
            for (int i = 11; i < Math.sqrt(desiredCapacity); i += 2) {
                if (desiredCapacity % i == 0) {
                    desiredCapacity += 2;
                    isComposite = true;
                    break;
                }
            }
            if (!isComposite) {
                isPrime = true;
            }
        }
    }
    return desiredCapacity;
}

