public static String unescapeJava(String str) throws Exception {
        String result = "";
        if (str == null) {
            return null;
        }
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c == '\\') {
                if (i < str.length() - 1) {
                    char nextChar = str.charAt(i + 1);
                    switch (nextChar) {
                        case 'b':
                            result += "\b";
                            break;
                        case 'f':
                            result += "\f";
                            break;
                        case 'n':
                            result += "\n";
                            break;
                        case 'r':
                            result += "\r";
                            break;
                        case 't':
                            result += "\t";
                            break;
                        case '\\':
                            result += "\\";
                            break;
                        default:
                            throw new Exception("Invalid escape sequence: " + nextChar);
                    }
                    i++;
                } else {
                    throw new Exception("Invalid escape sequence: " + c);
                }
            } else {
                result += c;
            }
        }
        return result;
    }

