protected int removeUnusedNodes() {
    int removedNodeCount = 0;
    Queue<Category> nodeQueue = new LinkedList<>();
    nodeQueue.add(root);

    while (!nodeQueue.isEmpty()) {
        Category currentNode = nodeQueue.poll();

        if (currentNode.isUnused()) {
            // Remove the current node from its parent's list of children
            if (currentNode.getParent() != null) {
                currentNode.getParent().getChildren().remove(currentNode);
            } else {
                // If the current node is the root node, remove it
                root = null;
            }

            // Recursively remove all children of the current node
            for (Category childNode : currentNode.getChildren()) {
                nodeQueue.add(childNode);
            }

            removedNodeCount++;
        } else {
            // Add all children of the current node to the queue
            for (Category childNode : currentNode.getChildren()) {
                nodeQueue.add(childNode);
            }
        }
    }

    return removedNodeCount;
}

