    // step 1: validate input
    if (uri == null) {
        return null;
    }

    // step 2: check if uri matches pattern
    Matcher matcher = this.uriPattern.matcher(uri);
    if (!matcher.matches()) {
        return null;
    }

    // step 3: extract matched groups
    Map<String, String> groupMap = new HashMap<>();
    for (int i = 0; i < matcher.groupCount(); i++) {
        String groupName = this.templateUri.getGroupName(i);
        String groupValue = matcher.group(i);
        groupMap.put(groupName, groupValue);
    }

    // step 4: return match result
    return new MatchResult(this.templateUri, groupMap);
}

