int addConstantNameAndType(final String name, final String descriptor) {
    // Initialize a hash code to 0
    int hashCode = 0;
    // Compute the hash code of the name and descriptor
    hashCode = (hashCode * 31) + name.hashCode();
    hashCode = (hashCode * 31) + descriptor.hashCode();
    // Check if an identical constant pool entry is already in the table
    ConstantPool constantPool = this. constantPool;
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPool.CPInfo info = constantPool.get(i);
        if (info instanceof ConstantPool.ConstantNameAndType) {
            ConstantPool.ConstantNameAndType constantNameAndType = (ConstantPool.ConstantNameAndType) info;
            if (name.equals(constantNameAndType.getName()) && descriptor.equals(constantNameAndType.getDescriptor())) {
                return constantNameAndType.hashCode();
            }
