private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
      return false;
    }
    ListNodeImpl<E> traversalNode = head;
    while (traversalNode != null) {
        if (traversalNode == node) {
            break;
        }
        traversalNode = traversalNode.next;
    }
    if (traversalNode == null) {
        return false;
    }
    if (traversalNode == head) {
        head = traversalNode.next;
    }
    if (traversalNode == tail) {
        tail = traversalNode.prev;
    }
    if (traversalNode.prev != null) {
        traversalNode.prev.next = traversalNode.next;
    }
    if (traversalNode.next != null) {
        traversalNode.next.prev = traversalNode.prev;
    }
    return true;
}

