public static final <V> void reverse(V[] arr, int from, int to) {
    // Reverses the order of the elements in the specified range within the given array.
    // @param < V > the type of elements in the array
    // @param arr the array
    // @param from the index of the first element (inclusive) inside the range to reverse
    // @param to the index of the last element (inclusive) inside the range to reverse

    // Exception handling
    if (arr == null || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Logic
    int mid = (from + to) / 2;
    for (int i = from; i <= mid; i++) {
        V temp = arr[i];
        arr[i] = arr[to - i];
        arr[to - i] = temp;
    }
}

public void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode<E> currentHead = list.head;
    ListNode<E> currentTail = list.tail;
    ListNode<E> newHead = currentHead.copy();
    ListNode<E> newTail = currentTail.copy();

    while (currentHead != null) {
        // Set the next node as the new head
        if (currentHead == newTail) {
            newTail = currentHead.getNext();
        } else {
            newHead = currentHead;
        }

        // Set the previous node as the new tail
        if (currentTail == newHead) {
            newHead = currentTail.getPrevious();
        } else {
            newTail = currentTail;
        }
    }

    if (newHead != null) {
        newHead.setPrevious(null);
    }

    if (newTail != null) {
        newTail.setNext(null);
    }

    head = newHead;
    tail = newTail;
}

