private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph graph){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (Edge edge : graph.edges()) {
        List<Pair<Integer,Integer>> minSeparator = computeMinSeparator(edge);
        Pair<List<Pair<Integer,Integer>>,E> pair = new Pair<>(minSeparator, edge);
        globalSeparatorList.add(pair);
    }
    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeMinSeparator(Edge edge){
    List<Pair<Integer,Integer>> minSeparator = new ArrayList<>();
    for (Edge e : edge.neighborhood()) {
        if (!minSeparator.contains(e)) {
            minSeparator.add(new Pair<>(e.getU(), e.getV()));
        }
    }
    return minSeparator;
}

