public ByteVector putInt(final int intValue) {
        int newLength = this.length + 4;
        if (newLength > this.data.length) {
            byte[] newData = new byte[Math.max(this.data.length << 1, newLength)];
            System.arraycopy(this.data, 0, newData, 0, this.length);
            this.data = newData;
        }
        byte[] bytes = new byte[4];
        for (int i = 0; i < 4; i++) {
            bytes[i] = (byte) (intValue >>> (i * 8));
        }
        System.arraycopy(bytes, 0, this.data, this.length, 4);
        this.length = newLength;
        return this;
    }

