private List<Integer> computeLowerBounds(List<K> keys) {
	List<Integer> lowerBounds = new ArrayList<>();
	if (keys.isEmpty()) {
		return lowerBounds;
	}

	for (int i = 0; i < keys.size(); i++) {
		lowerBounds.add(keys.get(i).intValue());
		for (int j = i + 1; j < keys.size(); j++) {
			if (keys.get(j).intValue() < lowerBounds.get(i)) {
				lowerBounds.set(i, keys.get(j).intValue());
			}
		}
	}

	return lowerBounds;
}

