public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Check if the relative path is a file name only
    if (!relativePath.contains("/")) {
        return path + "/" + relativePath;
    }

    // Check if the relative path is a folder path only
    if (relativePath.startsWith("/")) {
        return path.substring(0, path.lastIndexOf("/") + 1) + relativePath;
    }

    // Check if the relative path is a sub-folder path
    if (relativePath.startsWith("./")) {
        return path.substring(0, path.lastIndexOf("/") + 1) + relativePath.substring(2);
    }

    // Check if the relative path is a sibling folder path
    if (relativePath.startsWith("../")) {
        String siblingPath = path.substring(0, path.lastIndexOf("/"));
        siblingPath = siblingPath.substring(0, siblingPath.lastIndexOf("/") + 1);
        return siblingPath + relativePath.substring(3);
    }

    // If none of the above apply, treat the relative path as a full file path
    return relativePath;
}

