    if (previousNode == null || nextNode == null) {
        return null;
    }

    if (previousNode.isVirtual() && !nextNode.isVirtual()) {
        previousNode = previousNode.getRealNode();
    } else if (previousNode.isVirtual() && nextNode.isVirtual()) {
        nextNode = nextNode.getRealNode();
    }

    Edge edge = new Edge(previousNode, nextNode);
    previousNode = nextNode;
    nextNode = null;

    return edge;
}

